import { test } from 'node:test';
import assert from 'node:assert/strict';
import { spawn } from 'node:child_process';
import { mkdtemp, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { once } from 'node:events';

test('projects and tasks are validated, isolated, ordered, and retained after restart', async () => {
  const directory = await mkdtemp(join(tmpdir(), 'workboard-test-'));
  let child;
  let base;
  async function start() {
    child = spawn(process.execPath, ['server.js'], {
      env: { ...process.env, PORT: '0', DB_PATH: join(directory, 'nested', 'projects.sqlite') },
      stdio: ['ignore', 'pipe', 'pipe'],
    });
    let output = '';
    await new Promise((resolve, reject) => {
      const timer = setTimeout(() => reject(new Error('Server startup timed out')), 5000);
      child.once('error', error => { clearTimeout(timer); reject(error); });
      child.once('exit', code => { clearTimeout(timer); reject(new Error(`Server exited: ${code}`)); });
      child.stdout.on('data', data => {
        output += data;
        const match = output.match(/listening on port (\d+)/);
        if (match) {
          base = `http://127.0.0.1:${match[1]}`;
          clearTimeout(timer);
          resolve();
        }
      });
    });
  }
  async function stop() {
    const exited = once(child, 'exit');
    child.kill('SIGTERM');
    await exited;
    child = undefined;
  }
  async function create(name) {
    return fetch(`${base}/api/projects`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ name }),
    });
  }
  async function taskRequest(projectId, method = 'GET', body, taskId) {
    return fetch(`${base}/api/projects/${projectId}/tasks${taskId === undefined ? '' : `/${taskId}`}`, {
      method,
      headers: { 'Content-Type': 'application/json' },
      body: body === undefined ? undefined : JSON.stringify(body),
    });
  }
  try {
    await start();
    const health = await fetch(`${base}/health`);
    assert.equal(health.status, 200);
    assert.deepEqual(await health.json(), { status: 'ok' });
    assert.deepEqual(await (await fetch(`${base}/api/projects`)).json(), []);
    for (const name of ['', '   ', '\t\n']) {
      const response = await create(name);
      assert.equal(response.status, 400);
      assert.deepEqual(await response.json(), { error: 'Project name is required' });
    }
    assert.deepEqual(await (await fetch(`${base}/api/projects`)).json(), []);
    const firstResponse = await create('  First project  ');
    assert.equal(firstResponse.status, 201);
    const first = await firstResponse.json();
    assert.equal(first.name, 'First project');
    const second = await (await create('Second project')).json();
    assert.notEqual(first.id, second.id);
    assert.deepEqual(await (await fetch(`${base}/api/projects`)).json(), [first, second]);
    assert.deepEqual(await (await fetch(`${base}/api/projects/${first.id}`)).json(), first);
    for (const path of ['/', `/projects/${first.id}`, '/app.js', '/styles.css']) {
      assert.equal((await fetch(`${base}${path}`)).status, 200);
    }
    assert.equal((await fetch(`${base}/api/projects/9999`)).status, 404);
    assert.deepEqual(await (await taskRequest(first.id)).json(), []);
    for (const title of ['', '   ', '\t\n']) {
      const response = await taskRequest(first.id, 'POST', { title });
      assert.equal(response.status, 400);
      assert.deepEqual(await response.json(), { error: 'Task title is required' });
    }
    assert.deepEqual(await (await taskRequest(first.id)).json(), []);
    const taskResponse = await taskRequest(first.id, 'POST', { title: '  First task  ' });
    assert.equal(taskResponse.status, 201);
    const firstTask = await taskResponse.json();
    assert.equal(firstTask.title, 'First task');
    assert.equal(firstTask.completed, false);
    const secondTask = await (await taskRequest(first.id, 'POST', { title: 'Second task' })).json();
    const otherTask = await (await taskRequest(second.id, 'POST', { title: 'Other project task' })).json();
    assert.deepEqual(await (await taskRequest(first.id)).json(), [firstTask, secondTask]);
    assert.deepEqual(await (await taskRequest(second.id)).json(), [otherTask]);
    assert.equal((await taskRequest(second.id, 'PATCH', { completed: true }, firstTask.id)).status, 404);
    assert.equal((await taskRequest(9999, 'POST', { title: 'Orphan' })).status, 404);
    assert.equal((await taskRequest(first.id, 'PATCH', { completed: 'false' }, firstTask.id)).status, 400);
    for (const completed of [true, false, true]) {
      const response = await taskRequest(first.id, 'PATCH', { completed }, firstTask.id);
      assert.equal(response.status, 200);
      assert.deepEqual(await response.json(), { ...firstTask, completed });
    }
    firstTask.completed = true;
    await stop();
    await start();
    assert.deepEqual(await (await fetch(`${base}/api/projects`)).json(), [first, second]);
    assert.deepEqual(await (await fetch(`${base}/api/projects/${first.id}`)).json(), first);
    assert.deepEqual(await (await taskRequest(first.id)).json(), [firstTask, secondTask]);
    assert.deepEqual(await (await taskRequest(second.id)).json(), [otherTask]);
    assert.equal((await fetch(`${base}/projects/${first.id}`)).status, 200);
    const thirdTask = await (await taskRequest(first.id, 'POST', { title: 'Third task' })).json();
    assert.ok(thirdTask.id > otherTask.id);
    assert.equal(thirdTask.completed, false);
    const third = await (await create('Third project')).json();
    assert.ok(third.id > second.id);
  } finally {
    if (child) await stop();
    await rm(directory, { recursive: true, force: true });
  }
});
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFile } from 'node:fs/promises';
import { runInNewContext } from 'node:vm';

// A small DOM adapter exercises the shipped client without application dependencies.
class Element {
  constructor(tag) {
    this.tag = tag;
    this.children = [];
    this.attributes = {};
    this.events = {};
    this.value = '';
    this.hidden = false;
  }
  setAttribute(key, value) {
    this.attributes[key] = value;
    if (key === 'hidden') this.hidden = true;
    if (key === 'value') this.value = value;
  }
  append(...children) {
    this.children.push(...children);
    if (this.tag === 'select' && !this.value) this.value = children[0].value;
  }
  replaceChildren(...children) { this.children = children; }
  addEventListener(type, handler) { this.events[type] = handler; }
  focus() {}
  async emit(type) { await this.events[type]({ preventDefault() {} }); }
}

function descendants(node) {
  return [node, ...node.children.flatMap(descendants)];
}

test('project UI validates, creates, filters, and toggles tasks with accessible controls', async () => {
  const app = new Element('main');
  const tasks = [];
  let creates = 0;
  let writes = 0;
  const document = {
    querySelector: () => app,
    createElement: tag => new Element(tag),
  };
  const fetch = async (path, options = {}) => {
    let body;
    if (path === '/api/projects/1') body = { id: 1, name: 'Project' };
    else {
      assert.ok(path.startsWith('/api/projects/1/tasks'));
      if (options.method === 'POST') {
        creates++;
        body = { id: tasks.length + 1, title: JSON.parse(options.body).title, completed: false };
        tasks.push(body);
      } else if (options.method === 'PATCH') {
        writes++;
        body = tasks.find(task => task.id === Number(path.split('/').at(-1)));
        body.completed = JSON.parse(options.body).completed;
      } else body = tasks;
    }
    return { ok: true, json: async () => structuredClone(body) };
  };
  runInNewContext(await readFile(new URL('../public/app.js', import.meta.url), 'utf8'), {
    document, window: { location: { pathname: '/projects/1' } }, fetch,
  });
  await new Promise(resolve => setImmediate(resolve));
  const byId = id => descendants(app).find(node => node.attributes.id === id);
  const rows = () => descendants(app).filter(node => node.attributes['data-testid'] === 'task-row');
  const titles = () => rows().map(row => row.children[1].textContent);
  const form = descendants(app).find(node => node.tag === 'form');
  const input = byId('task-title');
  const filter = byId('task-filter');
  const alert = descendants(app).find(node => node.attributes.role === 'alert');
  assert.equal(descendants(app).find(node => node.tag === 'h1').textContent, 'Project');
  assert.ok(descendants(app).some(node => node.attributes.for === 'task-title' && node.textContent === 'Task title'));
  assert.ok(descendants(app).some(node => node.attributes.for === 'task-filter' && node.textContent === 'Task filter'));
  assert.ok(descendants(app).some(node => node.tag === 'button' && node.textContent === 'Create task'));
  assert.deepEqual(filter.children.map(node => node.textContent), ['All', 'Open', 'Completed']);
  assert.equal(filter.value, 'All');
  for (const value of ['', '   ', '\t\n']) {
    input.value = value;
    await form.emit('submit');
    assert.equal(alert.hidden, false);
    assert.match(alert.textContent, /Task title is required/);
    assert.equal(rows().length, 0);
  }
  assert.equal(creates, 0);
  for (const value of ['  First task  ', 'Second task']) {
    input.value = value;
    await form.emit('submit');
  }
  assert.equal(alert.hidden, true);
  assert.deepEqual(titles(), ['First task', 'Second task']);
  assert.equal(rows()[0].children[0].attributes['aria-label'], 'Complete First task');
  assert.equal(rows()[0].children[0].checked, false);
  rows()[0].children[0].checked = true;
  await rows()[0].children[0].emit('change');
  filter.value = 'Open';
  await filter.emit('change');
  assert.deepEqual(titles(), ['Second task']);
  filter.value = 'Completed';
  await filter.emit('change');
  assert.deepEqual(titles(), ['First task']);
  rows()[0].children[0].checked = false;
  await rows()[0].children[0].emit('change');
  assert.deepEqual(titles(), []);
  filter.value = 'All';
  await filter.emit('change');
  assert.deepEqual(titles(), ['First task', 'Second task']);
  assert.equal(rows()[0].children[0].checked, false);
  assert.equal(writes, 2);
});
