form { display: grid; grid-template-columns: 1fr auto; gap: 10px 12px; }
label { grid-column: 1 / -1; font-weight: 600; }
input, button, select { font: inherit; border-radius: 6px; padding: 10px 14px; }
input { min-width: 0; border: 1px solid #8a98aa; }
button { border: 1px solid #244a85; background: #244a85; color: white; cursor: pointer; }
button:hover { background: #183760; }
button:disabled { opacity: .6; cursor: wait; }
:focus-visible { outline: 3px solid #d88b12; outline-offset: 3px; }
.projects { padding: 0; margin: 28px 0 0; list-style: none; }
.project-row { display: flex; align-items: center; justify-content: space-between; gap: 20px; padding: 18px 0; border-bottom: 1px solid #dce2eb; }
.project-name { overflow-wrap: anywhere; min-width: 0; font-weight: 600; }
.project-row button { flex-shrink: 0; }
.alert { color: #a52121; }
.empty { color: #526175; }
.task-filters { display: flex; align-items: center; gap: 12px; margin-top: 24px; }
.tasks { padding: 0; margin: 20px 0 0; list-style: none; }
.task-row { display: flex; align-items: center; gap: 14px; padding: 18px 0; border-bottom: 1px solid #dce2eb; }
.task-row input { flex-shrink: 0; width: 20px; height: 20px; }
.task-title { overflow-wrap: anywhere; min-width: 0; }
.task-row:has(input:checked) .task-title { text-decoration: line-through; color: #526175; }
main > button { margin-bottom: 24px; }
@media (max-width: 600px) {
  main { margin: 20px 12px; padding: 24px 18px; }
  form { grid-template-columns: 1fr; }
  .project-row { gap: 12px; }
}

